import{_ as t,c as o,o as r,ah as s}from"./chunks/framework.RCw5T9E9.js";const c=JSON.parse('{"title":"Export and import","description":"","frontmatter":{"title":"Export and import"},"headers":[],"relativePath":"logs/export.md","filePath":"logs/export.md"}'),a={name:"logs/export.md"};function n(i,e,l,h,g,d){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="export-and-import" tabindex="-1">Export and import <a class="header-anchor" href="#export-and-import" aria-label="Permalink to &quot;Export and import&quot;">​</a></h1><p>Events from the <strong>Logs</strong> tab can be saved to an <strong>HTML</strong> report and opened again — in any browser or with <strong>Import Logs</strong> in Vue Inspector. This is useful for bug reports, for sharing a scenario with colleagues and for analysis outside the page.</p><p>General information about the tab: <a href="./general.html">Working with logs</a>.</p><hr><h2 id="export-format" tabindex="-1">Export format <a class="header-anchor" href="#export-format" aria-label="Permalink to &quot;Export format&quot;">​</a></h2><p>Every export is one <strong>HTML</strong> file: a static report for reading plus the structured event data that <strong>Import Logs</strong> reads back. There is no separate JSON export.</p><p>The data inside the report is compact, like the live log (see <a href="./general.html#how-events-are-stored">How events are stored</a>): store changes are diffs, a request and its response share one network entry, equal bodies are stored once, and identical values in any event are stored once as a shared snapshot. Titles, Before / After states, snapshot values and request / response details are restored when the report is opened.</p><p>The embedded data uses format version 1. A file from a newer or an older format is rejected with a message instead of being misread.</p><hr><h2 id="what-is-exported" tabindex="-1">What is exported <a class="header-anchor" href="#what-is-exported" aria-label="Permalink to &quot;What is exported&quot;">​</a></h2><h3 id="export-logs" tabindex="-1">Export Logs <a class="header-anchor" href="#export-logs" aria-label="Permalink to &quot;Export Logs&quot;">​</a></h3><ul><li>Without a selection — all events visible in the table after <strong>Search</strong> and <strong>Type</strong> filters.</li><li>With a selection — only the rows ticked in the checkbox column; the button shows <strong>Export Logs (n)</strong>.</li><li>Network events are always exported as a pair: when only <strong>Send request</strong> or only <strong>Receive response</strong> of a request is filtered or selected, the other event is added to the file too.</li></ul><p>The button is disabled while the filtered list is empty.</p><h3 id="single-event" tabindex="-1">Single event <a class="header-anchor" href="#single-event" aria-label="Permalink to &quot;Single event&quot;">​</a></h3><p><strong>Export event</strong> in the <strong>⋮</strong> menu of the details header or in the row context menu exports one event.</p><p>For network events the item is called <strong>Export request &amp; response</strong>: the <strong>Send request</strong> and <strong>Receive response</strong> events of the same request are exported together in one file, so the request and its response are never separated.</p><h3 id="pinia-changes-in-a-partial-export" tabindex="-1">Pinia changes in a partial export <a class="header-anchor" href="#pinia-changes-in-a-partial-export" aria-label="Permalink to &quot;Pinia changes in a partial export&quot;">​</a></h3><p>A <strong>Change store</strong> event is a diff against the previous event of the same store. When that previous event is not part of the export (a selection, a filter or a single event), the exported change also carries the full state after it and the old values of the changed fields, so <strong>Before</strong> / <strong>After</strong> stay available in the file.</p><h3 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Export</th><th>File name</th></tr></thead><tbody><tr><td><strong>Export Logs</strong></td><td><code>logs_&lt;date&gt;_&lt;time&gt;.html</code></td></tr><tr><td>Network pair</td><td><code>log_network_&lt;date&gt;_&lt;time&gt;.html</code></td></tr><tr><td>Other single event</td><td><code>log_&lt;type&gt;_&lt;date&gt;_&lt;time&gt;.html</code></td></tr></tbody></table><p>Data is masked at capture time, so the files contain the same masked values as the view (see <a href="./settings.html#data-masking">Logs settings</a>).</p><hr><h2 id="html-report" tabindex="-1">HTML report <a class="header-anchor" href="#html-report" aria-label="Permalink to &quot;HTML report&quot;">​</a></h2><p>The <strong>HTML</strong> report is one self-contained file: styles, scripts, the application icon and the event data are embedded. It uses a dark theme, does not load external resources and opens offline from disk.</p><h3 id="sidebar" tabindex="-1">Sidebar <a class="header-anchor" href="#sidebar" aria-label="Permalink to &quot;Sidebar&quot;">​</a></h3><ul><li><strong>Report</strong> — <strong>Overview</strong> and <strong>All events</strong> with the total count;</li><li>sections by type with counters: <strong>Network</strong> (<strong>Send request</strong>, <strong>Receive response</strong>), <strong>Components</strong> (<strong>Change props</strong>, <strong>Emit</strong>), <strong>Pinia</strong> (<strong>Change store</strong>, <strong>Store action</strong>), <strong>Page</strong> (<strong>Navigation</strong>, <strong>JS error</strong>);</li><li><strong>Download Vue Inspector</strong> at the bottom — link to the project page.</li><li><strong>Support Vue Inspector</strong> above it: <strong>Monthly support</strong> opens Boosty, <strong>Donate with USDT</strong> shows the Tron (TRC-20) address, a QR code and <strong>Copy address</strong>.</li></ul><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>Summary cards: <strong>Events</strong>, <strong>Errors</strong>, <strong>Failed requests</strong>, first and last event time, time span; counters by type; export information.</p><p><strong>Events</strong>, <strong>Errors</strong> and <strong>Failed requests</strong> are clickable: they open <strong>All events</strong> with the matching filter. The active filter is shown as a chip above the list; clicking the chip removes it.</p><h3 id="event-list-and-details" tabindex="-1">Event list and details <a class="header-anchor" href="#event-list-and-details" aria-label="Permalink to &quot;Event list and details&quot;">​</a></h3><ul><li>Search in the top bar; with <strong>in data</strong> enabled the search also looks inside event data.</li><li><strong>All events</strong> has a <strong>Type</strong> dropdown with checkboxes, the same control as on the <strong>Logs</strong> tab. Every type is on by default. <strong>Select all</strong> and <strong>Clear</strong> turn the whole list on or off. With every type off, the list is empty. The filter stays on this page while you search or use the <strong>Errors</strong> / <strong>Failed requests</strong> chip, and does not change the sidebar sections.</li><li>Clicking a row opens details with the same tabs as in the app (<strong>Overview</strong>, <strong>Params</strong>, <strong>Headers</strong>, <strong>Body</strong>, <strong>Changes</strong>, <strong>Before</strong> / <strong>After</strong>, <strong>State</strong>, <strong>Raw</strong>, etc.).</li><li>For network events, the button next to <strong>Close</strong> jumps between the request and its response.</li><li><strong>All events →</strong> in the details header opens <strong>All events</strong> and places this event at the top of the list. If its type was switched off, that type is switched on so the event stays in the list.</li><li><strong>↑ / ↓</strong> move between events, <strong>Esc</strong> closes details.</li><li>The selected section and event are kept in the address (<code>#…</code>), so a link to a specific event can be shared and survives a reload.</li></ul><hr><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><p><strong>Import Logs</strong> opens an <strong>HTML</strong> report exported from the <strong>Logs</strong> tab. The button is in the installed extension; Bookmark mode does not import logs.</p><ul><li>Imported events are shown in a separate read-only view. The banner shows the file name, the number of events and the export time.</li><li><strong>Back to live logs</strong> returns to live recording; live events are not lost while a file is open.</li><li>Invalid events are skipped (the number is shown in the import message).</li><li>HTML files that are not a Logs report are rejected with a message.</li><li>Imported data goes through the current masking settings once more.</li></ul><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./general.html">Working with logs</a></li><li><a href="./settings.html">Logs settings</a></li><li><a href="/qa-tools/docs/network/export.html">Export collections</a></li></ul>',38)])])}const m=t(a,[["render",n]]);export{c as __pageData,m as default};
